def max_value_on_paths(N, grid_values):
    # Initialize a 2D array to store the maximum sum of values collected on each path
    dp = [[0] * (N + 1) for _ in range(N + 1)]

    # Loop through each tuple in the grid_values list
    for x, y, value in grid_values:
        # If the current position is the top-left corner, set the maximum sum to the value
        if x == 1 and y == 1:
            dp[x][y] = value
        # If the current position is not the top-left corner, check if the position is valid
        elif x >= 1 and x <= N and y >= 1 and y <= N:
            # If the current position is not the bottom-right corner, update the maximum sum
            if x != N or y != N:
                dp[x][y] = max(dp[x - 1][y], dp[x][y - 1], dp[x - 1][y - 1]) + value
            # If the current position is the bottom-right corner, set the maximum sum to the value
            else:
                dp[x][y] = value

    # Return the maximum sum of values collected on the two paths
    return dp[N][N]
