def optimize_seating(M, N, K, L, D, chatting_pairs):
    # Initialize a matrix to store the number of chatting pairs that can be separated by adding an aisle in each position
    aisle_matrix = [[0] * (N + 1) for _ in range(M + 1)]

    # Loop through each chatting pair and count the number of pairs that can be separated by adding an aisle in each position
    for pair in chatting_pairs:
        x1, y1, x2, y2 = pair
        for i in range(x1, x2 + 1):
            for j in range(y1, y2 + 1):
                aisle_matrix[i][j] += 1

    # Initialize a list to store the optimal row and column indices for the aisles
    aisle_indices = []

    # Loop through each position and select the most effective positions for aisles
    for i in range(M):
        for j in range(N):
            if aisle_matrix[i][j] > 0:
                aisle_indices.append((i, j))

    # Sort the aisle indices by the number of chatting pairs they can separate
    aisle_indices.sort(key=lambda x: aisle_matrix[x[0]][x[1]], reverse=True)

    # Return the optimal row and column indices for the aisles
    return " ".join(str(i) for i, _ in aisle_indices[:K]), " ".join(str(j) for _, j in aisle_indices[:L])
