def decode(encoded: str, original: str, message: str) -> str:
    # Build a mapping from encoded letters to their original letters
    mapping = {}
    for i in range(len(encoded)):
        mapping[encoded[i]] = original[i]

    # Check if the mapping is valid
    if len(mapping) != len(set(mapping.values())):
        return "Failed"

    # Decode the message using the mapping
    decoded = ""
    for char in message:
        if char in mapping:
            decoded += mapping[char]
        else:
            return "Failed"

    return decoded
```

